SELECT


WHERE v.deleted = 0
  AND v.status != 0

    AND v.status = 1


    AND (
        m.model_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR b.brand_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR v.license_plate LIKE CONCAT('%', #{q.keyword}, '%')
        OR v.vehicle_no LIKE CONCAT('%', #{q.keyword}, '%')
    )


    AND m.category_code = #{q.categoryCode}


    AND v.brand_id = #{q.brandId}


    AND v.store_id = #{q.storeId}


    AND ROUND(v.daily_price * v.discount_rate, 2) >= #{q.minPrice}


    AND ROUND(v.daily_price * v.discount_rate, 2) <= #{q.maxPrice}



        ORDER BY final_price ASC, v.id DESC


        ORDER BY final_price DESC, v.id DESC


        ORDER BY v.id DESC


        ORDER BY v.rent_count DESC, v.id DESC


        ORDER BY v.rent_count DESC, v.view_count DESC, v.id DESC
